const existing = tdb.getCollectionNames();

for (const name of ["users","settings","team","invites","plots","sensors","readings","irrigation","alerts","rec_state","audit","counters"]) {
  if (!existing.includes(name)) {
    if (VALIDATORS[name]) tdb.createCollection(name, { validator: VALIDATORS[name], validationLevel: "strict", validationAction: "error" });
    else tdb.createCollection(name);
    print("created   " + name);
  } else {
    if (VALIDATORS[name]) tdb.runCommand({ collMod: name, validator: VALIDATORS[name] });
    print("updated   " + name + " (already existed)");
  }
  for (const [keys, opts] of (INDEXES[name] || [])) tdb.getCollection(name).createIndex(keys, opts);

  const docs = (DATA[name] || []).map(d => toDates(name, d));
  if (docs.length && tdb.getCollection(name).countDocuments({}, { limit: 1 }) === 0) {
    tdb.getCollection(name).insertMany(docs);
    print("  seeded  " + docs.length + " documents");
  }
}

for (const [name, v] of Object.entries(VIEWS)) {
  if (!existing.includes(name)) { tdb.createView(name, v.viewOn, v.pipeline); print("created   view " + name); }
}
print("\nDone. Database '" + DB_NAME + "' now has: " + tdb.getCollectionNames().join(", "));
